// Actual SDK browser execution with an injected recording executor, no Chrome process.
package main
import("bufio";"context";"encoding/json";"fmt";"os";"os/exec";"path/filepath";"strings";"github.com/gratefulagents/sdk/pkg/agentsdk";"github.com/gratefulagents/sdk/pkg/agentsdk/sandbox";"github.com/gratefulagents/sdk/pkg/agentsdk/tools/browser")
func must(err error){if err!=nil{panic(err)}}
type executor struct{dom string; exit int}
func(e executor)Build(context.Context,sandbox.Request)(*exec.Cmd,error){panic("not used")}
func(e executor)Run(_ context.Context,request sandbox.Request)(sandbox.Result,error){for _,arg:=range request.Argv {if path,ok:=strings.CutPrefix(arg,"--screenshot=");ok{must(os.WriteFile(path,[]byte("png-data"),0600))}};return sandbox.Result{Output:e.dom,ExitCode:e.exit},nil}
func main(){data,err:=os.ReadFile("../../fixtures/tools/browser.json");must(err);var cases []struct{Arguments json.RawMessage `json:"arguments"`;DOM string `json:"dom"`;Repeat int `json:"repeat"`;Exit int `json:"exit"`;ReadOnly bool `json:"read_only"`;Private *bool `json:"private"`};must(json.Unmarshal(data,&cases));var inputs []json.RawMessage;must(json.Unmarshal(data,&inputs));chrome,err:=os.MkdirTemp("","browser-bin-");must(err);defer os.RemoveAll(chrome);must(os.WriteFile(filepath.Join(chrome,"chromium"),[]byte("#!/bin/sh\nexit 1\n"),0700));must(os.Setenv("PATH",chrome));command:=exec.Command(os.Args[1]);command.Stderr=os.Stderr;stdin,err:=command.StdinPipe();must(err);stdout,err:=command.StdoutPipe();must(err);must(command.Start());defer func(){_=command.Process.Kill();_=command.Wait()}();encoder:=json.NewEncoder(stdin);scanner:=bufio.NewScanner(stdout);scanner.Buffer(make([]byte,65536),8<<20);
for index,test:=range cases {root,err:=os.MkdirTemp("","browser-test-");must(err);repeat:=test.Repeat;if repeat<=0{repeat=1};private:=true;if test.Private!=nil{private=*test.Private};base:=&browser.Tool{AllowPrivateNetworkURLs:private,Executor:executor{strings.Repeat(test.DOM,repeat),test.Exit},ScreenshotDir:root};var tool agentsdk.Tool=base;if test.ReadOnly{tool=base.ToolForAccess(agentsdk.ToolAccessLevelReadOnly)};expected,err:=tool.Execute(context.Background(),test.Arguments,root);must(err);encoded,err:=json.Marshal(expected.Content);must(err);must(json.Unmarshal(encoded,&expected.Content));must(encoder.Encode(inputs[index]));if !scanner.Scan(){panic("Rust replay stopped")};var actual struct{Result struct{Content []struct{Text string `json:"text"`} `json:"content"`;IsError bool `json:"is_error"`;ShouldPause bool `json:"should_pause"`} `json:"result"`;Image *string `json:"image"`};must(json.Unmarshal(scanner.Bytes(),&actual));image,err:=os.ReadFile(filepath.Join(root,"sub/test.png"));if err==nil&&(actual.Image==nil||*actual.Image!=string(image)){panic("screenshot mismatch")};must(os.RemoveAll(root));if actual.Result.IsError!=expected.IsError||actual.Result.ShouldPause!=expected.ShouldPause||len(actual.Result.Content)!=1||actual.Result.Content[0].Text!=expected.Content{panic(fmt.Sprintf("case %d: Go=%q error=%v Rust=%s",index,expected.Content,expected.IsError,scanner.Text()))}}
fmt.Printf("%d SDK browser command/result fixture cases verified\n",len(cases))}
